18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	import java.util.concurrent.atomic.AtomicLong;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import tools.jackson.databind.ObjectMapper;
28	import tools.jackson.databind.json.JsonMapper;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.service.IdempotencyStore;
47	import org.springframework.samples.petclinic.util.BusinessDays;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.servlet.http.HttpServletRequest;
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
67	     * memberId and registrationDate. */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    /** Serializes the structured {@link OwnerCreatedEvent} emitted on each create. */
71	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
72	
73	    /** Monotonically increasing sequence number assigned to each successful create's audit event. */
74	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
75	
76	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
77	    private static final int CITY_CAPACITY = 50;
78	
79	    /** Once a city already holds at least this many owners (but fewer than {@link #CITY_CAPACITY}),
80	     * a new owner created for that city is flagged with {@code capacityWarning} to signal the city
81	     * is approaching its capacity limit. */
82	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
83	
84	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
85	     * create is rejected once this many owners already carry today's registration date. */
86	    private static final int DAILY_REGISTRATION_LIMIT = 100;
87	
88	    /** Once more than this many owners already carry a given day's registration date, a new owner
89	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
90	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
91	
92	    /** HTTP header carrying the client-supplied idempotency key for a create. */
93	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
94	
95	    private final ClinicService clinicService;
96	
97	    private final OwnerMapper ownerMapper;
98	
99	    private final PetMapper petMapper;
100	
101	    private final VisitMapper visitMapper;
102	
103	    private final HttpServletRequest request;
104	
105	    private final IdempotencyStore idempotencyStore;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 HttpServletRequest request,
112	                                 IdempotencyStore idempotencyStore) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.request = request;
118	        this.idempotencyStore = idempotencyStore;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
150	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
151	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
152	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
153	        if (hasIdempotencyKey) {
154	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
155	                .map(this.clinicService::findOwnerById);
156	            if (existing.isPresent()) {
157	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
158	            }
159	        }
160	        HttpHeaders headers = new HttpHeaders();
161	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
162	        // The effective registration date (supplied, or the server date when omitted) must fall on
163	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
164	        // registration date — the stored value, the per-day limit below and the membership number —
165	        // uses this adjusted date.
166	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
167	        owner.setRegistrationDate(effectiveDate);
168	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
169	        // further creates for that day with 429 Too Many Requests.
170	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
171	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
172	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
173	        }
174	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
175	        // for its registration date, signalling a bulk-signup surge.
176	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
177	        // Per-city capacity: a city that already holds the maximum number of owners is full.
178	        int ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
179	        if (ownersInCity >= CITY_CAPACITY) {
180	            return new ResponseEntity<>(HttpStatus.CONFLICT);
181	        }
182	        // Capacity warning: flag this owner when its city already holds between the warning
183	        // threshold (40) and the hard limit (49), signalling the city is approaching capacity.
184	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
185	        // The household id is derived deterministically on the owner itself (see
186	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
187	        // last name and postcode share it automatically — no linking step and no ordering to manage.
188	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
189	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
190	        // (the SHA-256 of normalized telephone | lower-cased email-or-empty | soundex(lastName))
191	        // equals an existing owner's. A truly identical record is always rejected, independent of
192	        // sharesHousehold.
193	        if (this.clinicService.isIdentityKeyInUse(owner)) {
194	            return new ResponseEntity<>(HttpStatus.CONFLICT);
195	        }
196	        // Household membership: another owner may already belong to this (last name, postcode)
197	        // household. A new member is admitted rather than rejected — its membership level is instead
198	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
199	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
200	        // possible duplicate for review.
201	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
202	        // Soft "possible duplicate" detection: an existing owner's last name has the same Soundex
203	        // code and the same postcode, while its identity key differs (so it is not a hard
204	        // duplicate). A declared household member (sharesHousehold on an in-use household) is an
205	        // intentional share, not a suspected duplicate, so it is not flagged; otherwise the create
206	        // still proceeds, flagged with possibleDuplicate=true and possibleDuplicateOf set to the
207	        // matching owner id.
208	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
209	            ? null
210	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
211	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
212	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
213	        owner.setNamesakeCount(
214	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
215	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
216	        // current maximum level among its existing household members. Derive the cap from those
217	        // members' effective (already-capped) levels; with no existing member the cap stays null
218	        // and the owner's level is used uncapped.
219	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
220	        if (!householdMembers.isEmpty()) {
221	            int maxHouseholdLevel = householdMembers.stream()
222	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
223	                .max()
224	                .getAsInt();
225	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
226	        }
227	        this.clinicService.saveOwner(owner);
228	        // Compute the derived membership level once so the human-readable line and the structured
229	        // event below are guaranteed to report the identical value.
230	        int membershipLevel = ownerMapper.formatMembershipLevel(owner);
231	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
232	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
233	        // In addition to the human-readable audit line above, emit an immutable structured event.
234	        // The event carries the owner's current primary identifier (the memberId) via
235	        // Owner.getPrimaryIdentifier(), and a sequence number that strictly increases across creates.
236	        OwnerCreatedEvent event = new OwnerCreatedEvent(
237	            AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(), owner.getPrimaryIdentifier(),
238	            membershipLevel, OwnerCreatedEvent.EVENT_TYPE);
239	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
240	        if (hasIdempotencyKey) {
241	            this.idempotencyStore.record(idempotencyKey, owner.getId());
242	        }
243	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
252	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
253	        if (currentOwner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
257	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
258	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
259	        currentOwner.setCity(ownerFieldsDto.getCity());
260	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
261	        currentOwner.setLastName(ownerFieldsDto.getLastName());
262	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
263	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
264	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
265	        this.clinicService.saveOwner(currentOwner);
266	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Transactional
271	    @Override
272	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
273	        Owner owner = this.clinicService.findOwnerById(ownerId);
274	        if (owner == null) {
275	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
276	        }
277	        this.clinicService.deleteOwner(owner);
278	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
284	        Owner owner = this.clinicService.findOwnerById(ownerId);
285	        if (owner == null) {
286	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	        }
288	        HttpHeaders headers = new HttpHeaders();
289	        Pet pet = petMapper.toPet(petFieldsDto);
290	        owner.setId(ownerId);
291	        pet.setOwner(owner);
292	        pet.getType().setName(null);
293	        this.clinicService.savePet(pet);
294	        PetDto petDto = petMapper.toPetDto(pet);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
296	            .buildAndExpand(pet.getId()).toUri());
